//! Graph-owned construction and validation of durable release intents.
//!
//! This module deliberately does not call the legacy version or publish
//! planners. It observes one workspace directly and produces the exact
//! immutable authorization input used by later execution work.

use std::fs;

use callisto_model::{
    ArtifactDigest, DependencyResolver, Ecosystem, ExecutionTrustProfileV1, ReleaseInputComponentV1,
    ReleaseInputSnapshotV1, ReleaseIntentError, ReleaseIntentV1, ReleaseOperation, ReleaseOperationId,
    ReleasePackageId, SourceIdentity,
};

use crate::{GraphError, Workspace};

/// Builds the Git-bound release intent for every configured publishable
/// workspace package. Selection and execution adapters are deliberately
/// separate follow-on work; this builder has no side effects.
pub fn build_release_intent<R, D>(ws: &Workspace<'_, R, D>) -> Result<ReleaseIntentV1, GraphError>
where
    R: callisto_model::CommandRunner,
    D: DependencyResolver,
{
    let source = SourceIdentity::GitCommit {
        sha: ws.git_access().head_sha()?,
    };
    let snapshot = build_snapshot(ws, source)?;
    let operations = derive_operations(ws)?;
    ReleaseIntentV1::new(snapshot, ExecutionTrustProfileV1::GitCommit, operations)
        .map_err(GraphError::release_intent)
}

/// A graph-only validation capability. Its private field prevents callers
/// from manufacturing authorization from received JSON alone.
#[derive(Debug)]
pub struct ValidatedReleaseIntent {
    intent: ReleaseIntentV1,
}

impl ValidatedReleaseIntent {
    /// Returns the validated immutable intent for read-only inspection.
    pub fn intent(&self) -> &ReleaseIntentV1 {
        &self.intent
    }
}

/// Rebuilds all graph-owned release inputs from `ws`; no received plan is
/// trusted merely because its JSON is well formed.
pub fn validate_release_intent<R, D>(
    ws: &Workspace<'_, R, D>,
    received: ReleaseIntentV1,
) -> Result<ValidatedReleaseIntent, GraphError>
where
    R: callisto_model::CommandRunner,
    D: DependencyResolver,
{
    let expected = build_release_intent(ws)?;
    if received != expected {
        return Err(GraphError::ReleaseIntentValidationMismatch);
    }
    Ok(ValidatedReleaseIntent { intent: received })
}

fn build_snapshot<R, D>(
    ws: &Workspace<'_, R, D>,
    source: SourceIdentity,
) -> Result<ReleaseInputSnapshotV1, GraphError>
where
    R: callisto_model::CommandRunner,
    D: DependencyResolver,
{
    let mut components = Vec::new();
    let config = ws.root.join("callisto.toml");
    if config.exists() {
        components.push(file_component("config", &config, &ws.root)?);
    }
    for package in ws.graph.packages() {
        for manifest in &package.manifests {
            components.push(file_component("manifest", &ws.root.join(&manifest.path), &ws.root)?);
        }
    }
    Ok(ReleaseInputSnapshotV1::new(source, components))
}

fn file_component(
    category: &str,
    path: &std::path::Path,
    root: &std::path::Path,
) -> Result<ReleaseInputComponentV1, GraphError> {
    let bytes = fs::read(path).map_err(|error| callisto_model::ManifestError::Read {
        path: path.to_path_buf(),
        message: error.to_string(),
    })?;
    let relative = path.strip_prefix(root).map_err(|_| GraphError::ReleaseIntentValidationMismatch)?;
    let kind = format!("{category}:{}", relative.to_string_lossy().replace('\\', "/"));
    Ok(ReleaseInputComponentV1 {
        kind,
        fingerprint: callisto_model::SemanticInputDigest::from_transcript(&{
            let mut transcript = callisto_model::CanonicalTranscript::semantic_input_v1();
            transcript.push_str("path", relative.to_string_lossy().as_ref());
            transcript.push_str("bytes", ArtifactDigest::from_bytes(bytes).as_str());
            transcript
        }),
    })
}

fn derive_operations<R, D>(ws: &Workspace<'_, R, D>) -> Result<Vec<ReleaseOperation>, GraphError>
where
    R: callisto_model::CommandRunner,
    D: DependencyResolver,
{
    let versions = ws.base_versions()?;
    let mut operations = Vec::new();
    for package in ws.graph.packages() {
        let version = versions
            .get(&package.id)
            .expect("base_versions returns one entry for every graph package")
            .clone();
        let mut publish_ids = Vec::new();
        for target in &package.publish_to {
            let Some(ecosystem) = target.ecosystem() else {
                continue;
            };
            let Some(registry_key) = target.registry_key() else {
                continue;
            };
            let release_package = ReleasePackageId::new(ecosystem, package.id.name())
                .map_err(|error| GraphError::release_package(error.to_string()))?;
            let id = ReleaseOperationId::registry_publish(release_package.clone(), version.clone(), registry_key.0)
                .map_err(GraphError::release_operation)?;
            publish_ids.push(id.clone());
            operations.push(ReleaseOperation::new(id, vec![]).map_err(GraphError::release_operation)?);
        }
        if publish_ids.is_empty() {
            continue;
        }
        let ecosystem = package
            .canonical_manifests()
            .next()
            .map(|manifest| manifest.ecosystem())
            .unwrap_or(Ecosystem::Cargo);
        let release_package = ReleasePackageId::new(ecosystem, package.id.name())
            .map_err(|error| GraphError::release_package(error.to_string()))?;
        let tag = ReleaseOperation::tag(release_package.clone(), version.clone(), publish_ids)
            .map_err(GraphError::release_operation)?;
        let tag_id = tag.id().clone();
        operations.push(tag);
        if package
            .publish_to
            .iter()
            .any(|target| matches!(target, callisto_model::PublishTarget::GitHubRelease))
        {
            operations.push(
                ReleaseOperation::forge_release(release_package, version, vec![tag_id])
                    .map_err(GraphError::release_operation)?,
            );
        }
    }
    operations.sort_by(|left, right| left.id().cmp(right.id()));
    Ok(operations)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::locate::IgnoreWalkLocator;

    struct Runner;
    impl callisto_model::CommandRunner for Runner {
        fn run(
            &self,
            program: &str,
            args: &[&str],
            cwd: &std::path::Path,
        ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
            let output = std::process::Command::new(program)
                .args(args)
                .current_dir(cwd)
                .output()
                .map_err(|_| callisto_model::CommandError::NotFound {
                    program: program.to_string(),
                })?;
            Ok(callisto_model::CommandOutput {
                exit_code: output.status.code(),
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
            })
        }
    }

    fn workspace() -> (tempfile::TempDir, Runner) {
        let temp = tempfile::tempdir().unwrap();
        fs::write(
            temp.path().join("Cargo.toml"),
            "[package]\nname = \"release-fixture\"\nversion = \"1.2.3\"\nedition = \"2021\"\n",
        )
        .unwrap();
        for args in [
            ["init", "-q", "-b", "main"].as_slice(),
            ["config", "user.email", "test@example.com"].as_slice(),
            ["config", "user.name", "Test"].as_slice(),
            ["add", "."].as_slice(),
            ["commit", "-q", "-m", "init"].as_slice(),
        ] {
            assert!(std::process::Command::new("git")
                .args(args)
                .current_dir(temp.path())
                .status()
                .unwrap()
                .success());
        }
        (temp, Runner)
    }

    #[test]
    fn validates_direct_graph_intent_and_rejects_stale_snapshot() {
        let (temp, runner) = workspace();
        let locator = IgnoreWalkLocator::new(temp.path());
        let ws = Workspace::load(temp.path().to_path_buf(), &locator, &runner).unwrap();
        let intent = build_release_intent(&ws).unwrap();
        assert!(validate_release_intent(&ws, intent.clone()).is_ok());

        fs::write(
            temp.path().join("Cargo.toml"),
            "[package]\nname = \"release-fixture\"\nversion = \"1.2.4\"\nedition = \"2021\"\n",
        )
        .unwrap();
        assert!(matches!(
            validate_release_intent(&ws, intent),
            Err(GraphError::ReleaseIntentValidationMismatch)
        ));
    }
}

